/**
 * Who the dashboard says generated it.
 *
 * A small field with a name that disagreed with its only use site. It was
 * called `generatedFor`; the footer it feeds reads "Generated by X"; and the
 * default is `tallyd`, the tool. Read together those say the field means
 * *by*, and the name was the part that was wrong — but nothing had ever set
 * it, so the two readings had never been put side by side. A business name
 * placed in `generatedFor` would have come out claiming the business had
 * generated the file.
 */

import { describe, expect, it } from "vitest";
import { reviewDashboard } from "../docs/dashboard.js";
import { dashboardData } from "../src/dashboard/model.js";
import { renderDashboard } from "../src/dashboard/render.js";
import { generateBooks } from "../src/demo/generator.js";
import { bankView } from "../src/reconcile/bankView.js";
import { reconcile } from "../src/reconcile/matcher.js";
import { statementClosingBalance } from "../src/reconcile/bridge.js";
import { Money } from "../src/money/index.js";

function dashboard(credit?: string): string {
  const generated = generateBooks({ seed: 3, months: 1, invoicesPerMonth: 3, start: "2026-01-01" });
  const books = bankView(generated.ledger, generated.bankAccount);
  const zero = Money.zero(generated.currency);
  return renderDashboard(
    dashboardData({
      ledger: generated.ledger,
      account: generated.bankAccount,
      books,
      statement: generated.statement,
      result: reconcile(books, generated.statement),
      bankClosingBalance: statementClosingBalance(generated.statement, zero),
      bookClosingBalance: books.reduce((total, line) => total.plus(line.amount), zero),
      statementFormat: "csv",
      ...(credit === undefined ? {} : { generatedBy: credit }),
    }),
  );
}

describe("the footer credit", () => {
  it("names the tool when nothing is said", () => {
    expect(dashboard()).toContain("Generated by tallyd —");
  });

  it("is the model's field, not a constant in the template", () => {
    expect(dashboard("Ledgerwright Accounting")).toContain(
      "Generated by Ledgerwright Accounting —",
    );
    expect(dashboard("Ledgerwright Accounting")).not.toContain("Generated by tallyd");
  });

  it("escapes what it is given, because it reaches the page", () => {
    const html = dashboard('Smith & Sons <script>alert(1)</script>');
    expect(html).toContain("Smith &amp; Sons &lt;script&gt;");
    expect(html).not.toContain("<script>alert(1)</script>");
  });

  it("reads the same on the published dashboard", () => {
    // The docs site sets nothing, so the file it publishes is credited to the
    // tool — which is correct, and is the reading that made `by` the right
    // word and `For` the wrong one.
    expect(reviewDashboard().html).toContain("Generated by tallyd —");
  });
});
